// Üretilen dosya: tool/ozgun/uret.py. Doğa · Deniz canlıları ve mercan resifleri (kolay).
const ozNature9Kolay = <(String, String, List<String>, String)>[
  ('Süngerlerin hayvanlar âleminde diğer hayvanlardan ayrı, en ilkel grup olarak görülmesinin başlıca gerekçesi hangisidir?', 'Gerçek dokuları ve organları yoktur', ['Hücre duvarı taşıyan hücreleri vardır', 'Fotosentez yapan hücrelere sahiptirler', 'Yalnız eşeysiz ürerler'], 'Süngerlerde hücreler gevşek bir işbölümü gösterir ama sinir, kas gibi gerçek dokular ve organlar oluşmaz.'),
  ('Knidarlarda ağız ile anüsün durumu için aşağıdakilerden hangisi doğrudur?', 'Tek açıklık hem ağız hem anüs işi görür', ['Ağız ve anüs vücudun iki ayrı ucundadır', 'Anüs vardır ama ayrı bir ağız açıklığı yoktur', 'Ağız dokunaçların dışında, sırtta yer alır'], 'Knidarlarda sindirim boşluğunun (gastrovasküler boşluk) tek açıklığı vardır; besin buradan girer, artıklar buradan atılır.'),
  ('Bir denizanasının vücut kütlesinin yaklaşık yüzde 95\'inden fazlası neden oluşur?', 'Su', ['Protein', 'Yağ', 'Kalsiyum karbonat'], 'Denizanalarının jelatinimsi gövdesi büyük ölçüde sudan oluşur; bu yüzden karaya vurduklarında hızla kuruyup küçülürler.'),
  ('Tatlı suda yaşayan hidranın kendisinden büyük avları bile yakalayabilmesi hangi özelliğe dayanır?', 'Yakıcı hücrelerle avı felç etmesi', ['Avını sindirim sıvısıyla dışarıda eritmesi', 'Avı kum taneleriyle sarıp boğması', 'Avın arkasından hızla yüzerek onu yorması'], 'Hidra hareketsiz bekler; dokunaçlarına değen küçük kabukluları nematosistlerle felç edip ağzına götürür.'),
  ('Beyin mercanı adının kaynağı nedir?', 'Koloni yüzeyinin beyni andırması', ['Sinir sisteminin çok gelişmiş olması', 'Polip başına düşen çok sayıda sinir hücresi', 'Kafatası biçimindeki tek ve dev bir polip'], 'Beyin mercanlarında polipler kıvrımlı sıralar hâlinde dizilir ve yarım küre biçimli koloni beyin kıvrımlarını andırır.'),
  ('Mercan polipinin dokularındaki zooksantellerden aldığı en önemli katkı hangisidir?', 'Fotosentezle üretilen besinler', ['Avcılara karşı zehirli kimyasal salgılar', 'Kalsiyum karbonat iskeletin tamamı', 'Gece görüşü sağlayan özel pigmentler'], 'Zooksanteller fotosentez ürünlerinin büyük bölümünü polipe verir; bu, mercanın enerji gereksiniminin çoğunu karşılar.'),
  ('Kıyıya bitişik olarak gelişen ve kıyı ile arasında belirgin derin bir lagün bulunmayan resif tipi hangisidir?', 'Saçak (kıyı) resifi', ['Set resifi', 'Atol', 'Yama (lagün içi) resifi'], 'Saçak resifleri doğrudan kıyı çizgisinden denize doğru büyür; Kızıldeniz kıyılarındaki resiflerin çoğu bu tiptedir.'),
  ('Atol adalarının iklim değişikliği karşısında özellikle savunmasız olmasının başlıca nedeni hangisidir?', 'Deniz seviyesinden çok az yüksek olmaları', ['Altlarındaki volkanik etkinliğin sürmesi', 'Yoğun ve kuru ormanlarla kaplı olmaları', 'Kutup bölgelerine yakın soğuk sularda bulunmaları'], 'Atol adaları genellikle deniz seviyesinden çok az yüksektir; deniz seviyesinin yükselmesi ve fırtına dalgaları onları doğrudan tehdit eder.'),
  ('Resif mercanlarının çoğunda görülen yumurta ve spermin aynı anda suya bırakılıp döllenmenin suda gerçekleşmesine ne ad verilir?', 'Toplu yumurta bırakma', ['Polip içinde iç döllenme', 'Kuluçka kesesinde döllenme ve gelişme', 'Eşeysiz tomurcuklanma ile çoğalma'], 'Bu stratejide gametler suya saçılır; döllenme su kolonunda gerçekleşir.'),
  ('Cerrah balıklarına (surgeonfish) bu adın verilmesinin nedeni nedir?', 'Kuyruk sapındaki neşter gibi diken', ['Ölü balıkları temizleyip parçalamaları', 'Yaralı balıkların yaralarını yalayıp temizlemeleri', 'Çok ince ve uzun, bisturi gibi bir buruna sahip olmaları'], 'Cerrah balıklarının kuyruk sapının iki yanında bıçak gibi keskin kemiksi dikenler bulunur; savunmada ve kavgada kullanılır.'),
  ('Japonya\'da \'fugu\' olarak bilinen balon balığının yalnızca özel lisanslı aşçılar tarafından hazırlanabilmesinin nedeni nedir?', 'Zehirli organların etten ayrılması gerekir', ['Balığın etinin çok çabuk bozulup kokması', 'Pişirme sırasında ette zehir oluşabilmesi', 'Balığın nesli koruma altında olduğundan izin gerekmesi'], 'Fugu\'nun karaciğer, yumurtalık ve derisi yoğun tetrodotoksin içerebilir; bu organlar eğitimli aşçılarca dikkatle ayrılır.'),
  ('Vantuz benzeri sırt yüzgeciyle köpek balıklarına, mantalara ve kaplumbağalara yapışarak taşınan balık hangisidir?', 'Remora', ['Pilot balığı', 'Kalkan balığı', 'Uçan balık'], 'Remoranın sırt yüzgeci kaygan bir vantuza dönüşmüştür; konakçısına yapışıp taşınır ve artıklarla beslenir.'),
  ('Bazı keşiş yengeçlerinin taşıdığı salyangoz kabuğunun üstüne deniz şakayıkları yerleştirmesi ve yeni kabuğa geçerken şakayıkları da taşıması hangi ilişkiye örnektir?', 'İki tarafın da yarar gördüğü ortaklık', ['Yalnız yengecin zarar gördüğü asalaklık', 'Şakayığın yengeci avladığı avcılık', 'İki türün aynı besin için çekiştiği rekabet'], 'Şakayık yengeci yakıcı hücreleriyle korur, yengeç ise şakayığa hareket ve artık besin sağlar; ilişki karşılıklı yararlıdır.'),
  ('Tarihte Afrika ve Asya\'nın bazı bölgelerinde para olarak kullanılan deniz kabuğu hangisidir?', 'Kauri kabuğu', ['İstiridye kabuğu', 'Deniz tarağı kabuğu', 'Midye kabuğu'], 'Küçük ve dayanıklı kauri (Monetaria moneta) kabukları yüzyıllarca ticarette para birimi olarak kullanılmıştır.'),
  ('Yengeç, ıstakoz ve karides gibi kabukluların ait olduğu ve adını yürüme bacaklarının sayısından alan takım hangisidir?', 'Onayaklılar (Decapoda)', ['Eşayaklılar (Isopoda)', 'Yanyüzücüler (Amphipoda)', 'Kürekayaklılar (Copepoda)'], 'Decapoda üyelerinde beş çift, yani on yürüme bacağı bulunur; ilk çift çoğu zaman kıskaca dönüşmüştür.'),
  ('Bir yengecin kabuk değiştirdikten hemen sonraki birkaç gün içinde saklanmayı tercih etmesinin nedeni nedir?', 'Yeni kabuğu henüz yumuşaktır', ['Bu dönemde gözleri geçici olarak kör olur', 'Kabuk değiştirirken solungaçlarını kaybeder', 'Bu dönemde yalnız geceleri beslenebilir'], 'Eski kabuk atıldıktan sonra yeni dış iskelet su alarak genişler ve sertleşmesi zaman alır; bu sürede hayvan kolayca avlanabilir.'),
  ('Erkeklerinden birinin kıskacının diğerinden çok daha büyük olduğu ve bu dev kıskacı sallayarak dişilere gösteri yapan kıyı yengeci hangisidir?', 'Kemancı yengeç', ['Keşiş yengeci', 'Örümcek yengeç', 'Hindistan cevizi yengeci'], 'Kemancı yengeçlerin (Uca) erkeklerinde bir kıskaç çok büyüktür; çamur düzlüklerinde onu sallayarak kur yaparlar.'),
  ('Sırtlarına sünger, alg ve şakayık parçaları yapıştırarak çevreye karışan yengeçlere ne ad verilir?', 'Süsleyici yengeçler', ['Hayalet yengeçler', 'Keşiş (münzevi) yengeçleri', 'Kemancı yengeçler'], 'Süsleyici (dekoratör) yengeçler kabuklarındaki kancalı kıllara canlı parçalar tutturarak kamufle olur.'),
  ('Yumuşakçaların çoğunda kabuğu üreten doku hangisidir?', 'Manto', ['Radula', 'Ayak', 'Solungaç'], 'Kabuk, iç organları örten manto dokusunun salgıladığı kalsiyum karbonat ve proteinden oluşur.'),
  ('Bir istiridyede doğal inci oluşumunu başlatan olay hangisidir?', 'Mantoya yabancı bir cisim girmesi', ['Kabuğun güneşte kuruyup çatlaması', 'Yumurtaların kabuk içinde taşlaşması', 'Solungaçlarda tuz kristalleri birikmesi'], 'Mantoya giren yabancı madde çevresinde bir kese oluşur; bu kese katman katman sedef salgılayarak inciyi meydana getirir.'),
  ('İncinin ve kabuğun iç yüzeyinin gökkuşağı gibi parlamasını sağlayan tabakaya ne ad verilir?', 'Sedef', ['Kitin', 'Periostrakum', 'Mine'], 'Sedef (nacre), ince aragonit plakaların protein katmanlarıyla dizilmesinden oluşur; ışığın girişimi yanardöner parlaklık verir.'),
  ('İstiridye ve midye gibi süzücü yumuşakçaların kirli sularda toplanıp çiğ yenmesinin sağlık açısından riskli olmasının nedeni nedir?', 'Sudaki mikrop ve toksinleri biriktirirler', ['Etleri havayla temas edince zehre dönüşür', 'Kabuk parçaları mideye takılıp yara açar', 'Proteinleri insan tarafından hiç sindirilemez'], 'Süzücü beslenme bakteri, virüs ve alg toksinlerinin yumuşakçanın dokularında yoğunlaşmasına yol açar.'),
  ('Ahtapotun ağzında bulunan ve kabuklu avları kırmaya yarayan sert yapı hangisidir?', 'Papağanınkine benzer bir gaga', ['Kireçli diş sıraları', 'Kemikli çene plakaları', 'Yutaktaki solungaç dikenleri'], 'Kafadan bacaklıların ağzında kitin-protein yapılı sert bir gaga bulunur; kemiği olmayan vücudun en sert parçasıdır.'),
  ('Derisidikenlilerde tüp ayakların uçlarında bulunan ve yüzeye tutunmayı sağlayan yapı nedir?', 'Vantuz benzeri yapışkan uç', ['Kıskaç biçimli kitin kanca', 'Sert ve sivri kitin pençe', 'Zehirli yakıcı kapsül'], 'Tüp ayaklar su basıncıyla uzar; uçlarındaki vantuz ve yapışkan salgılar sayesinde yüzeye tutunur.'),
  ('Tulumlulara \'deniz fışkırtanı\' denmesinin nedeni nedir?', 'Sıkılınca sifonlarından su fışkırtmaları', ['Akıntıya karşı güçlü jet itkisiyle yüzmeleri', 'Kayalardan sürekli tuz kristalleri çıkarmaları', 'Geceleri sudan sıçrayıp ışık saçmaları'], 'Torba biçimli tulumlular sıkıştırıldığında içlerindeki suyu sifonlarından fışkırtır.'),
  ('Köpek balığı derisinin zımpara gibi pürüzlü olmasının nedeni hangisidir?', 'Dişe benzeyen plakoit pullar', ['Derideki kalın ve sert kıl örtüsü', 'Deri altında biriken ince kum taneleri', 'Üst üste binmiş sedef kaplı yuvarlak pullar'], 'Köpek balığı derisi dentin ve mineyle kaplı, dişe benzeyen plakoit pullarla örtülüdür; bu pullar suyun akışını da düzenler.'),
  ('Köpek balıklarının yalnızca yüzgeçleri kesilip gövdelerinin denize atılması uygulamasının ekolojik açıdan özellikle yıkıcı olmasının nedeni hangisidir?', 'Hayvan yüzemeyip ölür, tepe avcı azalır', ['Yüzgeçler hızla yeniden çıkar ve tür çoğalır', 'Denize atılan gövdeler suyun tuzluluğunu artırır', 'Yüzgeçlerin kesilmesi suya zehirli gaz salar'], 'Yüzgeç kesimi (finning) hem çok sayıda hayvanın ölümüne hem de besin ağının tepesindeki avcıların azalmasına yol açar.'),
  ('Dev manta vatozunun beslenme biçimi hangisidir?', 'Plankton süzerek beslenir', ['Büyük balıkları zehirli iğnesiyle avlar', 'Deniz tabanındaki midyeleri kırarak yer', 'Ölü balinaların leşini parçalayarak yer'], 'Mantalar başlarının iki yanındaki yüzgeç loblarıyla suyu ağza yönlendirir ve solungaç plakalarıyla plankton süzer; iğneleri yoktur.'),
  ('Vatozların bazı türlerinin kuyruğunda bulunan, kenarları testere gibi dişli ve zehirli diken insanlar için ne zaman tehlike oluşturur?', 'Kumda gizlenen vatoza basıldığında', ['Vatoz yüzeyde güneşlenirken uzaktan', 'Vatoz gece avlanırken bulunduğu yerden', 'Vatozun yumurta kılıfına dokunulduğunda'], 'Vatozlar saldırgan değildir; üstüne basılınca kuyruğu savurarak savunur. Sığ suda ayakları sürüyerek yürümek bunu önler.'),
  ('Deniz suyunda yaşayan kemikli bir balığın vücut sıvıları denizden daha az tuzludur. Bu balığın sürekli karşılaştığı sorun hangisidir?', 'Osmozla su kaybetmek', ['Osmozla aşırı su almak', 'Kanında tuz eksikliği', 'Vücudunun şişip patlaması'], 'Deniz suyu daha derişik olduğundan balığın vücudundan dışarı su çekilir; balık bunu telafi etmek zorundadır.'),
  ('Morina ve orkinos gibi deniz balıklarının milyonlarca küçük yumurta bırakmasına karşın popülasyonlarının patlamamasının nedeni nedir?', 'Yavruların çok azı erginliğe ulaşır', ['Bırakılan yumurtaların çoğu döllenmez', 'Erginler yumurtalarını yuvada korur', 'Larvalar yumurtadan çıkınca birbirini tamamen yer'], 'Yüksek sayıda küçük yumurta stratejisinde larva ölümü çok yüksektir; yalnız küçük bir oran yaşar.'),
  ('Yüzey sularında oluşan ölü plankton, dışkı ve mukus parçacıklarının sürekli olarak derinlere çökmesine verilen şiirsel ad nedir?', 'Deniz karı', ['Deniz köpüğü', 'Deniz tozu', 'Deniz yağmuru'], 'Deniz karı, ışık almayan derinliklerdeki pek çok canlının başlıca besin kaynağıdır.'),
  ('Derin deniz balıklarının çoğunun ağızlarının vücutlarına oranla çok büyük ve midelerinin esnek olmasının nedeni nedir?', 'Seyrek avı, büyük de olsa yutabilmek', ['Suyu süzerek içindeki tuzu ayırmak', 'Basınca karşı vücut duvarını sağlamlaştırmak', 'Solungaçlara daha çok oksijenli su almak'], 'Besinin kıt olduğu derinlerde karşılaşılan her av fırsatı değerlidir; dev ağız ve genişleyen mide büyük avları yutmayı sağlar.'),
  ('Yaz gecelerinde dalgaların ve kürek darbelerinin denizde mavi ışıklar saçmasına çoğunlukla hangi canlılar yol açar?', 'Işık üreten dinoflagellatlar', ['Fosfor minerali içeren kumlar', 'Denizanalarının yüzen yumurtaları', 'Ay ışığını yansıtan balık pulları'], 'Noctiluca scintillans gibi dinoflagellatlar hareketle uyarıldığında kısa mavi ışık çakar; buna halk arasında \'yakamoz\' denir.'),
  ('Plankton tanımında belirleyici olan özellik hangisidir?', 'Akıntıya karşı yüzememesi', ['Mikroskobik boyutta olması', 'Fotosentez yaparak besin üretmesi', 'Yalnız tuzlu suda yaşayabilmesi'], 'Planktonun ölçütü boyut değil, akıntılara karşı etkin yer değiştirememektir; dev denizanaları da plankton sayılır.'),
  ('Bir fitoplankton hücresi her gün bir kez bölünüyorsa, besin sınırlaması olmadığı varsayımıyla tek hücreden 10 gün sonra kaç hücre oluşur?', '1.024', ['20', '100', '10.240'], 'Her gün sayı ikiye katlanır: 2¹⁰ = 1.024 hücre.'),
  ('Kopepodların plankton besin ağındaki yeri en iyi nasıl tanımlanır?', 'Fitoplanktonu balıklara bağlayan halka', ['Besin ağının en tepesindeki avcı', 'Yalnız ölü maddeyle beslenen ayrıştırıcı', 'Fotosentez yapan birincil üretici'], 'Kopepodlar fitoplanktonla beslenir, kendileri de balık larvaları, hamsi ve ringa gibi balıkların temel besinidir.'),
  ('Dev kelp algleri (Macrocystis) yapraksı kısımlarının dibinde gaz dolu küçük keseler taşır. Bu keselerin işlevi nedir?', 'Yaprakları ışığa yakın tutmak', ['Gaz depolayıp gece solunum yapmak', 'Avcılar dokununca patlayıp onları korkutmak', 'Tohumları içinde taşıyıp akıntıyla yaymak'], 'Pnömatosist denen gaz keseleri alg gövdesini su yüzeyine doğru taşır; böylece fotosentez için daha çok ışık alınır.'),
  ('Dev kelplerin uygun koşullarda günde yaklaşık 50 cm uzayabildiği bildirilir. Bu hızla 30 günde kaç metre uzama olur?', '15 metre', ['1,5 metre', '150 metre', '5 metre'], '30 gün × 0,5 m/gün = 15 metre eder; kelp dünyanın en hızlı büyüyen canlılarından biridir.'),
  ('Deniz çayırlarının (Posidonia, Zostera gibi) alglerden temel farkı nedir?', 'Çiçekli bitkiler olmaları', ['Hiç fotosentez yapmayıp emerek beslenmeleri', 'Yalnız tatlı su göllerinde yaşayabilmeleri', 'Tek hücreli olup koloni oluşturmaları'], 'Deniz çayırları karadan denize dönmüş çiçekli bitkilerdir; algler ise gerçek kök, gövde ve çiçek taşımaz.'),
  ('Gelgit arası bölgede kayalara yapışık canlıların üst kuşakta karşılaştığı en büyük fiziksel stres hangisidir?', 'Havada kalıp kurumak ve ısınmak', ['Sürekli yüksek derin su basıncına maruz kalmak', 'Gün boyu tamamen karanlıkta kalmak', 'Suyun sürekli donma noktasında olması'], 'Üst kuşaktaki canlılar her gelgit döngüsünde saatlerce havada kalır; kuruma, güneş ısısı ve tuzluluk değişimi en büyük streslerdir.'),
  ('Alçalan suda kayalık bir havuzda kalan deniz şakayıklarının dokunaçlarını içeri çekip top gibi büzülmesinin yararı hangisidir?', 'Kurumayı azaltmak', ['Havuzdaki avcılarına saldırmak', 'Güneş ışığından daha çok yararlanmak', 'Suya yumurta bırakmaya hazırlanmak'], 'Büzülmüş şakayık yüzey alanını küçültür ve içindeki suyu tutar; böylece suyun geri gelmesine kadar kurumadan bekler.'),
  ('Kumsal kıyılarda dalgaların sürekli kumu karıştırması nedeniyle burada yaşayan canlıların çoğunun ortak uyumu hangisidir?', 'Kuma hızla gömülmek', ['Kayalara yapıştırıcıyla tutunmak', 'Kanatlanıp uçarak kaçmak', 'Kıyı bitkilerinin dallarında yuva kurmak'], 'Kumsal canlıları (kum solucanları, bazı midye ve yengeçler) tutunacak yüzey olmadığından kuma gömülerek dalga ve avcılardan korunur.'),
  ('İstanbul balıkçılığında \'çinekop\' adı hangi balığın genç bireylerine verilir?', 'Lüfer', ['Palamut', 'Kefal', 'Levrek'], 'Lüfer (Pomatomus saltatrix) boyuna göre defne yaprağı, çinekop, sarıkanat, lüfer ve kofana gibi adlar alır.'),
  ('Barbunya balığının çenesinin altındaki iki uzun bıyık (barbel) hangi işe yarar?', 'Tabanda besin aramaya', ['Rakip balıkları zehirleyip uzaklaştırmaya', 'Döllenmiş yumurtalarını taşımaya', 'Su yüzeyinden doğrudan hava almaya'], 'Barbunyanın bıyıkları tat ve dokunma alıcıları taşır; balık bunlarla tabanı yoklayarak küçük omurgasızları bulur.'),
  ('Türkiye\'de deniz ağ kafeslerinde en çok yetiştirilen iki balık türü hangileridir?', 'Levrek ve çipura', ['Hamsi ve palamut', 'Lüfer ve kofana', 'Barbunya ve istavrit'], 'Ege kıyılarındaki ağ kafes yetiştiriciliğinin büyük kısmını levrek ve çipura oluşturur; son yıllarda Karadeniz\'de alabalık da yetiştirilmektedir.'),
  ('Hamsinin sürü hâlinde yaşamasından balıkçıların yararlandığı av yöntemi hangisidir?', 'Gırgır ağıyla sürüyü çevirmek', ['Teker teker oltayla avlamak', 'Dalgıçların zıpkınla tek tek vurması', 'Kayalık kıyılardan elle toplamak'], 'Gırgır (çevirme) ağı, sonar ile bulunan sürüyü çepeçevre sarıp altını büzerek yakalar.'),
  ('Süveyş Kanalı hangi yıl açılmıştır?', '1869', ['1798', '1914', '1956'], 'Süveyş Kanalı 1869\'da açılmış; Lesepsiyen göç adını kanalın mimarı Ferdinand de Lesseps\'ten almıştır.'),
  ('Türkiye kıyılarında mutfakta en çok kullanılan midye türü olan ve Karadeniz ile Marmara\'da doğal yataklar oluşturan midye hangisidir?', 'Mytilus galloprovincialis', ['Zebra midyesi', 'Pina', 'Dev midye'], 'Midye dolma ve midye tavada kullanılan kara midye Mytilus galloprovincialis\'tir; Karadeniz ve Marmara\'da yaygındır.'),
  ('Avustralya kıyılarındaki yapraklı deniz ejderinin vücudundaki yaprak biçimli uzantıların işlevi nedir?', 'Yosunlar arasında gizlenmek', ['Yüzmeyi belirgin biçimde hızlandırmak', 'Dokunan avını zehirleyip felç etmek', 'Güneş ışığıyla fotosentez yapmak'], 'Yapraklı deniz ejderi (Phycodurus eques) bir denizatı akrabasıdır; uzantıları kahverengi alglere benzer ve yalnız kamuflaj sağlar.'),
  ('Denizatlarının çoğunun kuyruklarıyla deniz çayırlarına ya da mercan dallarına tutunarak durmasının nedeni nedir?', 'Akıntıya sürüklenmemek', ['Kuyruklarındaki solungaçlarla solunum yapmak', 'Kuyruk kıvrımında yumurta taşımak', 'Kuyruklarıyla avlarını sokup zehirlemek'], 'Denizatları dik duruşla küçük sırt yüzgeciyle yavaşça yüzer; kavrayıcı kuyrukları akıntıda yerinde kalmalarını sağlar.'),
  ('Bir balığın iç kulağında bulunan ve hem dengeyi hem de ses titreşimlerini algılamaya yardım eden kireçli taşlara ne ad verilir?', 'Otolit', ['Statosist', 'Radula', 'Spikül'], 'Otolitler iç kulaktaki duyu tüylerine göre farklı hareket ederek ses ve ivmeyi algılatır; yaş halkaları da taşır.'),
  ('Denizanalarının şemsiyelerini kasıp gevşeterek yüzmesi hangi hareket biçimine örnektir?', 'Su iterek tepkiyle ilerleme', ['Kirpik sıralarını çırparak kayma', 'Kaslı bir ayakla zeminde sürünme', 'Kanat benzeri uzantıları çırparak uçma'], 'Şemsiyenin kasılması altındaki suyu dışarı iter; tepki kuvveti denizanasını ters yöne iter.'),
  ('Denizyıldızları, yüzlerce tüp ayağını kullanarak yavaş hareket eder. Bu hareket sisteminin hangi kuvvetle çalıştığı doğru verilmiştir?', 'Su basıncıyla', ['Sinirlerin ürettiği elektrik akımıyla', 'İçlerindeki gaz kesesinin basıncıyla', 'Eklemli kemik kaldıraçlarıyla'], 'Tüp ayaklar su damar sistemindeki suyun basıncıyla uzar, kaslarla kısalır; yani hidrolik bir sistemdir.'),
  ('Mantaların ve vatozların yüzme biçimi, kuşlarda gördüğümüz hangi harekete en çok benzer?', 'Kanat çırparak uçmaya', ['Perdeli ayakla kürek çekmeye', 'Uzun bacaklarla zıplayarak koşmaya', 'Karın üstünde kayarak sürünmeye'], 'Mantalar ve vatozlar geniş göğüs yüzgeçlerini kanat gibi yukarı aşağı çırparak suda \'uçar\'.'),
  ('Bir dalgıç sığ bir resifte çıplak elle sert bir yüzeye dokunur ve elinde hemen yanma hissi başlar. Bu durum aşağıdakilerden hangisiyle en iyi açıklanır?', 'Yüzeyin ateş mercanı gibi yakıcı hücreli bir hidrozoa olması', ['Resif kayasının sıcak olması', 'Deniz suyunun tuzunun deriyi tahriş etmesi', 'Resifin elektrik yüklü olması'], 'Ateş mercanının yüzeyindeki yakıcı hücreler nematosistlerini teması anında ateşler; bu nedenle resiflere dokunulmamalıdır.'),
  ('Mercanların büyük çoğunluğunun kıyıya yakın sığ ve berrak sularda bulunması hangi gerekçeye bağlanır?', 'Simbiyotik alglerin fotosentez için ışığa ihtiyaç duyması', ['Mercanların avlarını yalnızca sığ suda bulması', 'Derin suda yeterince oksijen olmaması', 'Tuzluluğun derinlikle çok artması'], 'Resif yapıcı mercanların enerjisinin büyük kısmı zooksantellerden gelir; alglerin ışığa ihtiyacı olduğundan sığ su gerekir.'),
  ('Akdeniz\'de kırmızı mercan (Corallium rubrum) tarih boyunca hangi amaçla aranmıştır?', 'Takı ve süs eşyası yapımında', ['Boya ve yakıt elde etmek için', 'Gıda katkısı olarak', 'Gemi yapımında kereste olarak'], 'Kırmızı mercanın sert, kırmızı iskeleti kolye ve tespih yapımında değerlidir; aşırı avlanma stokları azaltmıştır.'),
  ('Ay denizanasının ağız çevresindeki dört halka biçimli yapı gözle bakıldığında nedir?', 'Üreme organları', ['Gözler', 'Beyin', 'Solungaçlar'], 'Aurelia aurita\'nın şemsiyesinde görünen at nalı biçimli dört halka eşey bezleridir.'),
  ('Deniz şakayığı sindirdiği besinin artığını nasıl atar?', 'Besini aldığı aynı ağız açıklığından dışarı çıkararak', ['Vücut yanındaki bir anüsten', 'Taban diskindeki deliklerden', 'Solungaçları aracılığıyla'], 'Knidarlarda sindirim boşluğunun tek açıklığı vardır; atıklar da ağızdan atılır.'),
  ('Bir mercan resifinin kayalık yapısı en çok hangi kimyasal bileşikten oluşur?', 'Kalsiyum karbonat', ['Sodyum klorür', 'Silisyum dioksit', 'Demir oksit'], 'Mercanlar deniz suyundaki kalsiyum ve bikarbonattan kalsiyum karbonat (kireç) iskeleti oluşturur.'),
  ('Keşiş yengeçleri büyüdükçe boş salyangoz kabukları arar. Bu davranışın nedeni aşağıdakilerden hangisidir?', 'Karınlarının yumuşak ve korumasız olması', ['Kabuk bulmadan ürememeleri', 'Kabuğun onlara yüzerlik kazandırması', 'Kabuğun yiyecek sağlaması'], 'Keşiş yengeçlerinin karnı sert bir kabukla örtülü değildir; boş salyangoz kabuğu bu bölgeyi korur.'),
  ('Kabuğunu yeni değiştirmiş bir yengeç neden genellikle saklanır?', 'Yeni kabuk sertleşene kadar çok savunmasız olduğu için', ['Yumurtalarını bırakacağı için', 'Soğuk suya girmekten kaçındığı için', 'Avlanmak için pusu kurduğu için'], 'Kabuk değişiminden sonra vücut yumuşaktır; sertleşme tamamlanana kadar avcılara karşı korunmasızdır.'),
  ('Kril (Euphausia superba) en çok hangi bölgede devasa sürüler oluşturur?', 'Güney Okyanusu', ['Karadeniz', 'Kızıldeniz', 'Akdeniz'], 'Antarktika kril sürüleri milyarlarca bireyden oluşur ve balinaların, penguenlerin, foklar için temel besindir.'),
  ('Kafadan bacaklılarda kromatoforlar neyi sağlar?', 'Çok hızlı renk ve desen değiştirmeyi', ['Işık üretmeyi', 'Su içinde nefes almayı', 'Kabuk büyümesini'], 'Derideki kromatofor hücreleri sinir kontrolüyle genişleyip daralarak saniyeler içinde renk değiştirir.'),
  ('Deniz kestanesinin ağız bölgesindeki, dişli ve beş parçalı çiğneme aygıtına ne denir?', 'Aristo feneri', ['Radula', 'Kirri', 'Astaksantin keseciği'], 'Aristo feneri beş keskin diş taşıyan kompleks bir yapıdır; deniz kestanesi onunla yosun ve kaya yüzeyini kazır.'),
  ('Denizyıldızının bir kolu kopsa yeniden gelişebilir. Bazı türlerde kopan kolun da yeni bir birey oluşturabilmesi hangi yeteneğin sonucudur?', 'Aşırı yenilenme', ['Partenogenez', 'Metamorfoz', 'Hermafroditlik'], 'Ortak merkezi disk parçasını da taşıyan kollar, yenilenme ile bütün bir yıldız oluşturabilir.'),
  ('Köpek balıklarında diş kaybı ve yenilenmesi nasıl gerçekleşir?', 'Çenede sıralar hâlinde dizilmiş yedek dişler öne doğru ilerler', ['Dişler hiç dökülmez', 'Dişler yılda bir kez bir bütün olarak değişir', 'Yalnızca yavruluk döneminde diş çıkarlar'], 'Köpek balıklarında dişler ömür boyu sürekli yenilenir; yedek sıralar ön sıranın yerini alır.'),
  ('Mantalar (Manta) ve balina köpek balığı gibi dev balıkların ortak özelliği nedir?', 'Büyük gövdelerine rağmen planktonla beslenmeleri', ['Zehirli iğneyle avlanmaları', 'Karada yumurtlamaları', 'Yalnızca derin sularda bulunmaları'], 'Bu devler su akıntısını süzerek zooplanktonu yakalar; yırtıcı olmaları gerekmez.'),
  ('Kemikli balıklarda solungaçları dışarıdan örten ve su akımını yöneten sert yapıya ne ad verilir?', 'Solungaç kapağı', ['Yüzme kesesi', 'Yan çizgi', 'Spiracle'], 'Kemikli balıklarda operkulum solungaçları korur ve pompa gibi su akışına yardım eder; köpek balıklarında bulunmaz.'),
  ('Balığın pul sayısı ya da halkalarına bakılarak ne tahmin edilebilir?', 'Yaklaşık yaşı ve büyüme dönemleri', ['Cinsiyeti', 'Yediği besini', 'Ne kadar derine indiği'], 'Pullarda ve kulak taşında (otolit) mevsimsel büyüme halkaları oluşur; yaş tayini için kullanılır.'),
  ('Balık yüzme kesesindeki gazın dengelenmesi, balığın neyi ayarlamasını sağlar?', 'Yüzmeden suda sabit derinlikte kalabilmesini', ['Tuz miktarını', 'Vücut ısısını', 'Görüş mesafesini'], 'Yüzme kesesindeki gaz miktarı artınca balık yükselir, azalınca batar; böylece enerji harcamadan belli derinlikte durur.'),
  ('Mezopelajik bölgede yaşayan birçok balık (örneğin lanternfish, fener balıkları) geceleri yüzeye yaklaşır, gündüz derine iner. Bu davranışa ne ad verilir?', 'Günlük dikey göç', ['Mevsimsel göç', 'Üreme göçü', 'Kıyı göçü'], 'Gece besin zengini yüzeyde beslenip gündüz avcılardan karanlıkta saklanmak yoğun bir göç hareketidir; dünyanın en büyük hayvan göçü sayılır.'),
  ('Kırmızı gelgit olaylarında deniz suyunun kızıl-kahverengiye dönmesine hangi canlılar yol açar?', 'Dinoflagellat alg patlamaları', ['Kırmızı mercanlar', 'Deniz yıldızları', 'Karides sürüleri'], 'Bazı dinoflagellatlar aşırı çoğalınca suyu renklendirir; bazıları toksin üreterek balık ve kabuklu ölümlerine yol açar.'),
  ('Okyanuslarda atmosferdeki oksijenin yaklaşık yarısına yakınını hangi grup üretir?', 'Fitoplankton', ['Deniz çayırları', 'Balıklar', 'Mercan poliplerinin kendisi'], 'Mikroskobik fotosentetik alglerin ve siyanobakterilerin oksijen üretimi, karadaki bitkilerle kıyaslanabilir büyüklüktedir.'),
  ('Kopepodlar (Calanus) okyanustaki en bol çok hücreli hayvanlar arasında sayılır. Bunun ekolojik anlamı nedir?', 'Fitoplankton enerjisini balıklara taşıyan temel halka olmalarıdır', ['Yüzeyde ışık üretmeleridir', 'Mercanları beslemeleridir', 'Gelgiti oluşturmalarıdır'], 'Kopepodlar fitoplanktonla beslenir; ringa, hamsi gibi balıkların başlıca besinidir.'),
  ('Kırmızı alglerden elde edilen agar, laboratuvarda ne amaçla kullanılır?', 'Mikroorganizma yetiştirme besiyeri hazırlamak için jelleştirici olarak', ['Işık kaynağı olarak', 'Soğutucu sıvı olarak', 'Çözücü olarak'], 'Agar, bakteri ve mantarların üretildiği katı besiyerlerinin temel jelleştiricisidir.'),
  ('Japon mutfağında suşi sarmakta kullanılan nori, hangi canlı grubundan elde edilir?', 'Kırmızı algler', ['Deniz çayırları', 'Kahverengi kelp', 'Sünger iskeleti'], 'Nori, Porphyra cinsi kırmızı alglerin ince tabaka hâline getirilmiş kurutulmuş biçimidir.'),
  ('Akdeniz\'deki Posidonia oceanica çayırlarının sağladığı faydalardan biri aşağıdakilerden hangisidir?', 'Kıyı erozyonunu azaltması ve yavru balıklara barınak olması', ['Suyu tuzlandırması', 'Balıkları zehirlemesi', 'Petrol üretmesi'], 'Posidonia çayırları kumu tutar, dalgaları yavaşlatır ve birçok türe yuva/üreme alanı sağlar.'),
  ('Gelgit arası bölgede, gelgit çekilince sudan çıkan canlıların kurumaya karşı gösterdiği en yaygın davranış hangisidir?', 'Kabuklarını sıkıca kapatıp ya da kayalara yapışarak nemi korumak', ['Havadan oksijen almak', 'Yeni kabuk üretmek', 'Karada yürüyüp sulak yere gitmek'], 'Midye, patella ve palamut kabuğunu kapatarak içlerini nemli tutar; çekilme saatlerinde su kaybı azalır.'),
  ('Karadeniz\'de her yıl sonbaharda büyük sürüler hâlinde Karadeniz\'in kuzeyinden Marmara ve Boğaz yönüne inen balıklardan biri hangisidir?', 'Hamsi', ['Barbun', 'Orfoz', 'Kırlangıç balığı'], 'Hamsi (Engraulis encrasicolus) kışlamak için güneye göçer; Türkiye\'de Karadeniz balıkçılığının en önemli türüdür.'),
  ('Kızıldeniz kökenli bir balık olan gümüş balon balığı Akdeniz\'e hangi yolla ulaşmıştır?', 'Süveyş Kanalı üzerinden', ['Gemi balastıyla Karadeniz\'den', 'Cebelitarık Boğazı\'ndan', 'Basra Körfezi\'nden kara yoluyla'], 'Süveyş Kanalı\'nın açılmasıyla Kızıldeniz türleri Doğu Akdeniz\'e geçmiştir (lesepsiyen göç).'),
  ('Türkiye\'de Ege ve Akdeniz\'de görülen kılıç balığı (Xiphias gladius) hangi özelliğiyle ayırt edilir?', 'Üst çenesinin uzayıp yassı bir kılıç biçimini alması', ['Vücudunun yassı olması', 'Sırtında hiç yüzgeç taşımaması', 'Çok küçük boyda olması'], 'Kılıç balığı hızlı yüzen, büyük bir yırtıcıdır ve kılıcını avı yaralamada kullanır.'),
  ('Çanakkale ve Ege kıyılarında doğal süngerin hasadında yüzyıllarca hangi yöntem kullanılmıştır?', 'Serbest dalış ve tüplü olmadan taşla inen dalgıçlar', ['Büyük ağlar', 'Yalnızca makineyle kazıma', 'Kimyasal çözümle'], 'Ege\'de, özellikle Bodrum çevresinde, sünger avcıları (sünger dalgıçları) uzun yıllar yalnızca nefesleriyle dalmıştır.'),
  ('Karadeniz\'de deniz tarağı olarak yaygın olarak bilinen canlı hangi gruba girer?', 'Çift kabuklu yumuşakça', ['Derisidikenli', 'Kabuklu', 'Denizanası'], 'Taraklar (Pecten, Flexopecten) çift kabukludur ve kabuklarını açıp kapatarak kısa mesafe yüzebilirler.'),
  ('Barbun balığı çenesinin altındaki ince çıkıntılarla ne yapar?', 'Kumdaki avı dokunarak ve tatla algılayıp bulur', ['Elektrik üretir', 'Işık saçar', 'Avını zehirler'], 'Barbunların çene bıyıkları (barbel) tat ve dokunma algılayıcılarıyla doludur; yemi kum altında arar.'),
  ('Sardalya ve hamsi gibi küçük pelajik balıkların insan beslenmesindeki önemi hangi besin özelliğine dayanır?', 'Omega-3 yağ asitlerince zengin olmaları', ['Kalsiyum kabuğu taşımaları', 'Yüksek şeker içermeleri', 'Hiç yağ içermemeleri'], 'Yağlı küçük balıklar omega-3 bakımından zengindir; besin zincirinin altlarında yer aldıkları için ağır metal birikimi de düşüktür.'),
  ('Jacques Cousteau\'nun geliştirdiği ve 1943\'te Emile Gagnan ile birlikte tamamladığı Aqualung buluşu deniz biyolojisi araştırmalarına ne kazandırdı?', 'Dalgıçlara serbestçe ve uzun süre sualtında çalışma olanağı', ['Kıyıdan uzak balık avı', 'Kimyasal analiz', 'Sesle haberleşme'], 'Aqualung, basınçlı hava tüpünü regülatörle birleştirerek dalgıçların hareket serbestliğini artırdı.'),
  ('Ammonitler (amonitler) Mezozoyik denizlerinin yaygın canlılarıydı. Bu canlılar hangi gruba aittir?', 'Kafadan bacaklılar', ['Kabuklular', 'Derisidikenliler', 'Balıklar'], 'Ammonitler sarmal kabuklu kafadan bacaklılardı; Kretase sonunda soyları tükendi, kabukları iyi bir fosil kılavuzudur.'),
  ('Su altında yaşayan canlıların suda yüzerken enerji harcamasını azaltan vücut biçimine ne denir?', 'Hidrodinamik (akımçizgisel) biçim', ['Işınsal simetri', 'Kabuklu gövde', 'Eşey dimorfizmi'], 'Torpido biçimli vücut sürtünmeyi azaltır; ton balığı ve yunus buna örnektir.'),
  ('Uçan balıkların (Exocoetidae) sudan çıkıp süzülmesi neye hizmet eder?', 'Yırtıcılardan kaçmaya', ['Yumurta bırakmaya', 'Güneşlenmeye', 'Havadan oksijen almaya'], 'Büyük göğüs yüzgeçleri sayesinde yüzlerce metre süzülerek ton balığı ve kılıç balığı gibi avcılardan kaçarlar.'),
  ('Denizatı (Hippocampus) hareket ederken nasıl bir yol izler?', 'Küçük sırt yüzgecini hızla titreterek dik konumda ilerler', ['Jet itişiyle fırlar', 'Kuyruğuyla yürür', 'Gövdesini ağ gibi açar'], 'Denizatları zayıf yüzücülerdir; kuyruklarını bitkilere dolayarak akıntıda tutunurlar.'),
  ('Resif üzerinde yaşayan temizleyici lapina (Labroides) balığı başka balıkların derisindeki parazitleri yer. Bu ilişki için hangisi doğrudur?', 'Karşılıklı yarar sağlayan ortak yaşamdır', ['Parazitliktir', 'Yarar görmeyen ortak yaşamdır', 'Rekabettir'], 'Temizleyici balık besin bulurken, konuk balık parazitlerden kurtulur; mutualizm örneğidir.'),
  ('Bir mercan resifinde bir yılda %2 olan mercan örtüsü kaybı, yirmi yıl boyunca aynı oranda (bileşik değil, başlangıç değerine göre) sürerse toplam kayıp yüzde kaç olur? Başlangıç örtüsü %100 sayılsın.', '%40', ['%20', '%60', '%2'], 'Her yıl başlangıç değerinin %2\'si kaybedildiğinden 20 × 2 = %40 kayıp olur.'),
  ('Mercan ağarmasını doğrudan tetikleyen aşağıdaki etkenlerden hangisi en iyi bilinendir?', 'Su sıcaklığının uzun süre yükselmesi', ['Su sıcaklığının hafif düşmesi', 'Suyun ışığı artırması', 'Resifte yeni balık türlerinin çoğalması'], 'Aşırı sıcak stres altındaki mercan, zooksantellerini atar ve beyazlaşır; ısı dalgaları ağarmanın başlıca nedenidir.'),
  ('Kuzey Atlantik\'te yaşayan bir ringa sürüsünde binlerce balık aynı anda yön değiştirir. Bu uyum hangi duyuyla en çok sağlanır?', 'Yan çizgi ve görme', ['Koku', 'Tat', 'Işık üretimi'], 'Sürü balıkları komşularının hareketini yan çizgi ve görme yoluyla algılar; böylece koordineli hareket eder.'),
  ('Karides ve yengeç gibi kabuklulardaki bileşik gözler ne tür görüntü verir?', 'Birçok küçük göz biriminden oluşan mozaik görüntü', ['Tek odaklı net görüntü', 'Yalnız ışık yönü', 'Kızılötesi görüntü'], 'Bileşik gözler yüzlerce ommatidyumdan oluşur; hareket algılamada üstündür.'),
];
